<main class="main"><div class="main__inner"><form class="settings-page" method="post" action="<?= url('/admin/settings/theme-language') ?>"><?= csrf_field() ?><header class="settings-page__header"><div><h1>Theme &amp; Language</h1><p>Store the institute interface preferences without changing the approved layout.</p></div><button class="btn btn--primary">Save Preferences</button></header><section class="settings-card"><div class="settings-card__body"><div class="settings-grid"><div class="form-field"><label class="form-label">Theme</label><select class="form-select" name="theme"><option value="maroon" <?= ($institute['theme']??'maroon')==='maroon'?'selected':'' ?>>Maroon</option><option value="system" <?= ($institute['theme']??'')==='system'?'selected':'' ?>>Follow system preference</option></select></div><div class="form-field"><label class="form-label">Language</label><select class="form-select" name="language"><option value="en" <?= ($institute['language']??'en')==='en'?'selected':'' ?>>English</option><option value="ur" <?= ($institute['language']??'')==='ur'?'selected':'' ?>>Urdu</option></select></div></div><div class="inline-info"><i data-lucide="info"></i><span>The selected language is stored for localized content; untranslated labels continue to use English.</span></div></div></section></form></div></main>
